graph_results.sql:
SELECT mid, title, year, rating, num_votes
FROM public.movie
WHERE year = 2018;

SELECT mid, title, year, rating, num_votes
FROM public.movie
WHERE num_votes > 100000;

SELECT mid, title, year, rating, num_votes
FROM public.movie
WHERE year BETWEEN 2010 AND 2015;

SELECT m1.mid AS movie1_id, m1.title, m1.year AS year1, m2.mid AS movie2_id, m2.year AS year2
FROM public.movie m1
JOIN public.movie m2 ON m1.title = m2.title AND m1.year <> m2.year AND m1.mid < m2.mid;

SELECT mid, title, year, rating, num_votes
FROM public.movie
WHERE title ILIKE '%love%';

